-- LOZA store v2. Additive, repeatable migration; existing orders and mono_events are untouched.
-- Apply to grape-orders BEFORE deploying the matching PR. Do not wrap in BEGIN/COMMIT on D1.
CREATE TABLE IF NOT EXISTS loza_store_migrations (
  version TEXT PRIMARY KEY,
  applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS products (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL CHECK(length(name) BETWEEN 2 AND 160),
  price_kop INTEGER CHECK(price_kop IS NULL OR (typeof(price_kop) = 'integer' AND price_kop BETWEEN 1 AND 100000000)),
  available INTEGER NOT NULL DEFAULT 0 CHECK(available IN (0,1)),
  stock INTEGER NOT NULL DEFAULT 0 CHECK(typeof(stock) = 'integer' AND stock >= 0),
  is_demo INTEGER NOT NULL DEFAULT 0 CHECK(is_demo IN (0,1)),
  details_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(details_json)),
  CHECK(available = 0 OR price_kop IS NOT NULL)
);
CREATE TABLE IF NOT EXISTS order_checkout (
  order_id TEXT PRIMARY KEY REFERENCES orders(id) ON DELETE RESTRICT,
  request_key_hash TEXT NOT NULL UNIQUE CHECK(length(request_key_hash) = 64),
  payload_hash TEXT NOT NULL CHECK(length(payload_hash) = 64),
  buyer_name TEXT NOT NULL CHECK(length(buyer_name) BETWEEN 2 AND 100),
  phone TEXT NOT NULL CHECK(length(phone) = 13),
  city TEXT NOT NULL CHECK(length(city) BETWEEN 2 AND 100),
  delivery_method TEXT NOT NULL CHECK(delivery_method IN ('nova_poshta','ukrposhta')),
  delivery_branch TEXT NOT NULL CHECK(length(delivery_branch) BETWEEN 1 AND 180),
  comment TEXT NOT NULL DEFAULT '' CHECK(length(comment) <= 1000),
  items_json TEXT NOT NULL CHECK(json_valid(items_json) AND json_type(items_json) = 'array' AND json_array_length(items_json) BETWEEN 1 AND 20),
  demo_only INTEGER NOT NULL CHECK(demo_only IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS order_items (
  order_id TEXT NOT NULL REFERENCES order_checkout(order_id) ON DELETE RESTRICT,
  product_id TEXT NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
  product_name TEXT NOT NULL,
  quantity INTEGER NOT NULL CHECK(typeof(quantity) = 'integer' AND quantity BETWEEN 1 AND 5),
  unit_price_kop INTEGER NOT NULL CHECK(typeof(unit_price_kop) = 'integer' AND unit_price_kop > 0),
  line_total_kop INTEGER NOT NULL CHECK(line_total_kop = quantity * unit_price_kop),
  PRIMARY KEY(order_id, product_id)
);
CREATE TABLE IF NOT EXISTS checkout_rate_limits (
  bucket_key TEXT PRIMARY KEY,
  window_start INTEGER NOT NULL,
  hits INTEGER NOT NULL CHECK(hits > 0)
);
CREATE INDEX IF NOT EXISTS idx_checkout_rate_window ON checkout_rate_limits(window_start);
CREATE INDEX IF NOT EXISTS idx_checkout_created ON order_checkout(created_at);
CREATE INDEX IF NOT EXISTS idx_order_items_product ON order_items(product_id);
CREATE INDEX IF NOT EXISTS idx_products_public ON products(is_demo, available);

-- These triggers run only on the NEW checkout table, never on old orders or bank events.
CREATE TRIGGER IF NOT EXISTS loza_checkout_validate_v2
BEFORE INSERT ON order_checkout
BEGIN
  SELECT CASE WHEN EXISTS (
    SELECT 1 FROM json_each(NEW.items_json) j
    LEFT JOIN products p ON p.id = json_extract(j.value, '$.productId')
    WHERE p.id IS NULL OR p.available <> 1 OR p.price_kop IS NULL
       OR p.stock < json_extract(j.value, '$.quantity')
       OR json_type(j.value, '$.quantity') <> 'integer'
       OR json_extract(j.value, '$.quantity') NOT BETWEEN 1 AND 5
  ) THEN RAISE(ABORT, 'LOZA_STOCK_UNAVAILABLE') END;
  SELECT CASE WHEN (
    SELECT COUNT(DISTINCT json_extract(value, '$.productId')) FROM json_each(NEW.items_json)
  ) <> json_array_length(NEW.items_json)
  THEN RAISE(ABORT, 'LOZA_DUPLICATE_ITEM') END;
END;
CREATE TRIGGER IF NOT EXISTS loza_checkout_reserve_v2
AFTER INSERT ON order_checkout
BEGIN
    SELECT NEW.order_id, p.id, p.name, json_extract(j.value, '$.quantity'), p.price_kop,
           p.price_kop * json_extract(j.value, '$.quantity')
    FROM json_each(NEW.items_json) j
    JOIN products p ON p.id = json_extract(j.value, '$.productId');
  SELECT CASE WHEN (
    SELECT COUNT(*) FROM order_items WHERE order_id = NEW.order_id
  ) <> json_array_length(NEW.items_json) OR (
    SELECT COALESCE(SUM(line_total_kop), 0) FROM order_items WHERE order_id = NEW.order_id
  ) <> (SELECT amount_kop FROM orders WHERE id = NEW.order_id)
  THEN RAISE(ABORT, 'LOZA_TOTAL_MISMATCH') END;
  UPDATE products SET stock = stock - (
    SELECT quantity FROM order_items WHERE order_id = NEW.order_id AND product_id = products.id
  ) WHERE id IN (SELECT product_id FROM order_items WHERE order_id = NEW.order_id);
END;

